export const HOME_STATES: ReadonlyArray<HomeStateId> = ['home-begin', 'home-return', 'home-unclaimed-writing', 'home-many-works'];

export function isHomeState(v: unknown): v is HomeStateId {
  return typeof v === 'string' && (HOME_STATES as ReadonlyArray<string>).includes(v);
}
export function isReviewState(v: unknown): v is ReviewStateId {
  return isFixtureState(v) || isHomeState(v);
}

/** A Work the member has DECLARED. `returnPlace` exists only where durable place evidence does. */
export type HomeWork = {
  id: string;
  title: string;
  kind: string;
  facts: string;
  written: string;
  image: keyof typeof IMAGES;
  returnPlace?: { chapter: string; title: string };
};

/** Writing that exists but no Work has claimed. It is never called a Work. */
export type HomeWriting = { id: string; title: string; pages: string; written: string };

